		LmdbPersistentAdjacencyBenchmark.Expected writerExpected;
		int added;
		boolean writerOpen;
		final IntConsumer addedRow = row -> added++;

		@Setup(Level.Trial)
		public void setupTrial() throws IOException {
			require(mutationCount > 0 && statementCount >= mutationCount, "aligned fixture dimensions");
			require(operation.equals("NOVEL") || operation.equals("DUPLICATE"), "aligned operation");
			require(shape.equals("DENSE") || shape.equals("MIXED"), "aligned row shape");
			directory = Files.createTempDirectory("rdf4j-persistent-adjacency-aligned-");
			store = new TripleStore(directory.toFile(), new LmdbStoreConfig("spoc,posc").setAutoGrow(false)
					.setForceSync(false)
					.setTripleDBSize(256L << 20), null);
			base = new long[statementCount][];
			store.startTransaction();
			writerOpen = true;
			for (int row = 0; row < statementCount; row++) {
				long subject = shape.equals("DENSE") ? 10 : 100_000L + row / 8;
				long predicate = shape.equals("DENSE") ? 20 : 20 + row % 8;
				base[row] = new long[] { subject, predicate, 200_000L + 2L * row, row % 2 == 0 ? 0 : 7 };
				require(store.storeTriple(base[row][0], base[row][1], base[row][2], base[row][3], true),
						"unique aligned seed");
			}
			store.commit();
			writerOpen = false;
			baseExpected = expected(base, -1, -1, -1, -1);
			changed = new long[mutationCount][];
			subjects = new long[mutationCount];
			predicates = new long[mutationCount];
			objects = new long[mutationCount];
			contexts = new long[mutationCount];
			int first = (statementCount - mutationCount) / 2;
			for (int row = 0; row < mutationCount; row++) {
				changed[row] = base[first + row].clone();
				if (operation.equals("NOVEL")) {
					changed[row][2]++;
				}
				subjects[row] = changed[row][0];
				predicates[row] = changed[row][1];
				objects[row] = changed[row][2];
				contexts[row] = changed[row][3];
			}
			long[][] complete = base;
			if (operation.equals("NOVEL")) {
				complete = Arrays.copyOf(base, statementCount + mutationCount);
				System.arraycopy(changed, 0, complete, statementCount, mutationCount);
			}
			writerExpected = expected(complete, -1, -1, -1, -1);
			verifyBase();
		}

