	public long alignedBatch(AlignedState state) throws IOException {
		state.store.storeTriplesAligned(state.subjects, state.predicates, state.objects, state.contexts,
				state.mutationCount, true, state.addedRow);
		long expected = state.operation.equals("NOVEL") ? state.mutationCount : 0;
		require(state.added == expected, "aligned mutation callback count");
		return state.added;
	}
